// Existing Windows PowerShell and Playwright only. Never reads real session folders.
const fs=require('node:fs'),path=require('node:path'),cp=require('node:child_process'),crypto=require('node:crypto'),assert=require('node:assert/strict'),{chromium}=require('playwright');
const root=path.resolve(__dirname,'../..'),moduleDir=process.argv[2]?path.resolve(process.argv[2]):path.join(root,'实用小工具/Codex会话交接评估/windows-local');
if(!moduleDir.startsWith(root+path.sep))throw Error('Test module must remain inside this workspace');
const instance='test-'+Date.now(),data=path.join(moduleDir,'.local',instance),connection=path.join(data,'connection.json');
const output=path.join(root,'.planning/windows-session-desk-tests');fs.mkdirSync(output,{recursive:true});
const ps=path.join(process.env.SystemRoot,'System32/WindowsPowerShell/v1.0/powershell.exe');
const args=['-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-File',path.join(moduleDir,'Start-SessionDesk.ps1'),'-NoBrowser','-Instance',instance];
const original=fs.readFileSync(path.join(moduleDir,'../check-codex-session.ps1'));
let server,base,token,browser;const checks=[];const passed=n=>checks.push(n),id=n=>'00000000-0000-0000-0000-'+String(n).padStart(12,'0');
const delay=ms=>new Promise(r=>setTimeout(r,ms));
async function start(){server=cp.spawn(ps,args,{windowsHide:true,stdio:'ignore'});for(let i=0;i<100;i++){if(fs.existsSync(connection)){const c=JSON.parse(fs.readFileSync(connection,'utf8'));if(c.pid===server.pid){[base,token]=c.url.split('#');return;}}if(server.exitCode!==null)throw Error('server startup failed: '+(fs.existsSync(path.join(data,'startup-error.txt'))?fs.readFileSync(path.join(data,'startup-error.txt'),'utf8'):'unknown'));await delay(100);}throw Error('startup timeout');}
async function api(route,body,headers={}){const response=await fetch(base+route,{method:body===undefined?'GET':'POST',headers:{'X-SessionDesk':token,...(body===undefined?{}:{'Content-Type':'application/json'}),...headers},body:body===undefined?undefined:JSON.stringify(body)});return {status:response.status,data:await response.json()};}
async function stop(){if(server&&server.exitCode===null){try{await api('api/shutdown',{});}catch{}for(let i=0;i<100&&server.exitCode===null;i++)await delay(50);if(server.exitCode===null){server.kill();throw Error('service did not stop gracefully');}}}
(async()=>{try{await start();passed('Windows PowerShell no-elevation service start');
const runtime=fs.readFileSync(path.join(data,'runtime/isolated-analyzer.ps1'),'utf8').replace(/^\uFEFF/,'');const source=original.toString('utf8').replace(/^\uFEFF/,'');const literal="'"+path.join(data,'fixtures').replaceAll("'","''")+"'";assert.equal(source.split('$env:USERPROFILE').length-1,4);assert.equal(runtime.replaceAll(literal,'$env:USERPROFILE'),source);passed('only four fixture path substitutions');
assert.equal((await api('api/tasks',undefined,{'X-SessionDesk':'invalid'})).status,403);assert.equal((await api('api/tasks',undefined,{'Origin':'https://untrusted.invalid'})).status,403);assert.equal((await api('api/unknown',{})).status,404);passed('token origin and route restrictions');
const duplicate=cp.spawnSync(ps,args,{encoding:'utf8',windowsHide:true,timeout:10000});assert.equal(duplicate.status,0);assert.match(duplicate.stdout,/already running/);assert.equal(JSON.parse(fs.readFileSync(connection)).pid,server.pid);passed('single state writer');
browser=await chromium.launch({channel:'msedge',headless:true});const page=await browser.newPage();const errors=[];let external=0;page.on('pageerror',e=>errors.push(e.message));page.on('request',r=>{if(/^https?:/.test(r.url())&&!r.url().startsWith(base))external++;});
await page.goto(base+'#'+token);await page.waitForFunction(()=>document.getElementById('notice').textContent.includes('已连接'));
async function save(n,name){await page.locator('#name').fill(name);await page.locator('#id').fill(id(n));await page.locator('#save').click();await page.waitForFunction(()=>!document.getElementById('save').disabled);}
await save(1,'资料整理 · 北岸');await save(2,'资料整理 · 灯塔');await save(3,'缺失日志验证');assert.equal((await api('api/tasks')).data.tasks.length,3);passed('save custom name and ID');
await page.locator('#search').fill('灯塔');assert.equal(await page.locator('.task').count(),1);await page.locator('#search').fill('');passed('search saved tasks');
await page.locator(`[data-query="${id(1)}"]`).click();const repeat=await api('api/query',{id:id(1)});assert.equal(repeat.status,200);const firstRun=repeat.data.run;assert.equal((await api('api/query',{id:id(1)})).data.run,firstRun);passed('duplicate running query reuses job');
await page.locator(`[data-query="${id(2)}"]`).click();await page.waitForFunction(()=>document.getElementById('status').textContent==='查询完成',{},{timeout:20000});assert.equal(await page.locator('#selectedId').textContent(),id(2));assert.match(await page.locator('#output').textContent(),/虚构会话 2/);passed('concurrent task outputs remain assigned');
const job=(await api('api/job?id='+id(2))).data;assert.equal(await page.locator('#output').textContent(),job.output);assert.match(job.output,/一、基本信息/);assert.match(job.output,/三、交接建议/);passed('right pane shows original terminal sections');
const direct=cp.spawnSync(ps,['-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-File',path.join(data,'runtime/Invoke-IsolatedAnalyzer.ps1'),'-TaskId',id(2),'-ReportPath',path.join(data,'reports',id(2)+'.md')],{encoding:'utf8',windowsHide:true,timeout:20000});assert.equal(direct.status,0,direct.stderr);assert.equal(direct.stdout,job.output);passed('UI output equals direct isolated analyzer output');
await page.locator('#reportButton').click();await page.waitForFunction(()=>!document.getElementById('reportPanel').hidden);assert.match(await page.locator('#report').textContent(),/这是隔离的虚构测试输入/);passed('local detailed report');
await page.locator(`[data-query="${id(3)}"]`).click();await page.waitForFunction(()=>document.getElementById('status').textContent==='查询失败',{},{timeout:20000});assert.equal(await page.locator('#reportButton').isDisabled(),true);assert.doesNotMatch(await page.locator('#output').textContent(),/虚构会话 2/);passed('missing synthetic session fails without stale output');
assert.equal((await api('api/tasks',{action:'save',id:'x; calc',name:'bad'})).status,400);await save(4,'未开放真实查询');assert.equal((await api('api/query',{id:id(4)})).status,400);assert.equal((await api('api/report?id=../../tasks.json')).status,404);passed('invalid IDs unsupported data and arbitrary report paths rejected');
await save(1,'重命名后保留');assert.equal((await api('api/tasks')).data.tasks.length,4);assert.equal((await api('api/tasks')).data.tasks.find(t=>t.id===id(1)).name,'重命名后保留');passed('rename upserts instead of duplicate');
await api('api/tasks',{action:'delete',id:id(4)});passed('delete task');
await page.screenshot({path:path.join(output,'local-only.png'),fullPage:true});
const savedBytes=fs.readFileSync(path.join(data,'tasks.json'));await stop();await start();assert.ok(fs.readFileSync(path.join(data,'tasks.json')).equals(savedBytes));await page.goto(base+'#'+token);await page.waitForFunction(()=>document.getElementById('notice').textContent.includes('已连接'));assert.equal(await page.locator('.task').count(),3);assert.equal((await api('api/tasks')).data.tasks.find(t=>t.id===id(1)).name,'重命名后保留');assert.equal((await api('api/job?id='+id(1))).status,404);passed('service restart restores disk task list but not stale results');
await page.locator(`[data-query="${id(1)}"]`).click();await page.waitForFunction(()=>document.getElementById('status').textContent==='查询完成',{},{timeout:20000});passed('query after restart');
await page.setViewportSize({width:390,height:844});assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));passed('390px no horizontal overflow');
assert.ok(fs.readFileSync(path.join(moduleDir,'../check-codex-session.ps1')).equals(original));assert.deepEqual(errors,[]);assert.equal(external,0);passed('original unchanged and no external page traffic');
await page.locator('#shutdown').click();await page.waitForFunction(()=>document.getElementById('notice').textContent.includes('服务已退出'));await stop();passed('UI shutdown retains task file');
const result={checks,count:checks.length,browser:browser.version(),mode:'isolated-synthetic',errors,external};fs.writeFileSync(path.join(output,'result.json'),JSON.stringify(result,null,2));console.log(JSON.stringify(result));
}finally{if(browser)await browser.close();await stop();}})().catch(e=>{console.error(e);process.exitCode=1;});
